    C c;
    constructor(C _c) { c = _c; }
    function run(address maybeNewOwner) public payable {
        // read initial owner
        address before = c.owner();

        // try to call transferOwnership and record whether it reverted
        bool reverted;
        try c.transferOwnership(maybeNewOwner) {
            reverted = false;
        } catch {
            reverted = true;
