contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // single public test entry
    function run(address newOwnerForSetup) public payable {
        // we will attempt to make this contract the owner if possible by calling transferOwnership
        // record current owner
        address beforeOwner = c.owner();

        // Try to become owner: only succeeds if this contract is already owner. Record revert status.
        bool transferReverted;
        try c.transferOwnership(address(this)) {
            transferReverted = false;
        } catch {
            transferReverted = true;
        }

        // After the attempt, read owner
        address afterOwner = c.owner();

        // Now try calling owned() and record whether it reverts.
        bool ownedReverted;
        try c.owned() {
            ownedReverted = false;
        } catch {
            ownedReverted = true;
        }

        // General rule: owned() does not revert iff c.owner() equals this contract's address.
        // Use the observed afterOwner (owner after any attempted transferOwnership).
        assert(ownedReverted ? (afterOwner != address(this)) : (afterOwner == address(this)));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // single public test entry
    function run(address newOwner, bool attemptTransfer) public payable {
        require(newOwner != address(0) ); // parameter constraint only

        // Read owner before any state-changing calls
        address ownerBefore = c.owner();

        // Optionally attempt a state change: transferOwnership may revert if caller isn't owner
        bool transferReverted;
        if (attemptTransfer) {
            try c.transferOwnership(newOwner) {
                transferReverted = false;
            } catch {
                transferReverted = true;
            }
        } else {
            // no attempt made
            transferReverted = true;
        }

        // Read owner after the (possible) transfer
        address ownerAfter = c.owner();

        // Assert the invariant: if transfer succeeded then ownerAfter == newOwner; if transfer reverted or wasn't attempted then ownerAfter == ownerBefore.
        assert(transferReverted ? (ownerAfter == ownerBefore) : (ownerAfter == newOwner));
    }
    receive() external payable {}
}

