contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // param newOwner: address to attempt to transfer ownership to
    // param callAsOwner: if true, the test contract will be set as owner first so the subsequent transferOwnership should succeed; otherwise transferOwnership should revert
    function run(address newOwner, bool callAsOwner) public payable {
        require(newOwner != address(0));

        // read initial owner
        address ownerBefore = c.owner();

        // If we want the transfer to succeed, first make this contract the owner by calling transferOwnership from the current owner.
        // The only way to become owner is to have the current owner call transferOwnership. Since the test contract is the msg.sender for calls to c,
        // we simulate both scenarios: if callAsOwner is true and current owner is this contract, the transfer we make next should succeed.
        // If callAsOwner is true but this contract is not ownerBefore, try to make ownerBefore transfer ownership to this contract by calling c.transferOwnership.
        // However we cannot make arbitrary external addresses call c. So the only guaranteed owner we can make is if ownerBefore == address(this).
        // To allow a successful transfer in some executions, if ownerBefore != address(this) and callAsOwner is true, we attempt to transfer ownership from address(this) and
        // rely on it reverting; the assertion below must hold in either case.

        bool preconditionThisIsOwner = (ownerBefore == address(this));

        // Attempt the transfer and record whether it reverted
        bool reverted;
        // We must call transferOwnership as this contract (msg.sender = address(this)).
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();

        // General rule to assert:
        // If the call did not revert, then ownerAfter equals newOwner.
        // If the call reverted, then ownerAfter equals ownerBefore (unchanged).
        // This captures that only successful transferOwnership updates owner, and failed calls do not change it.
        assert((!reverted && ownerAfter == newOwner) || (reverted && ownerAfter == ownerBefore));
    }

    receive() external payable {}
}
